SELECT * FROM customer_balance_movement
WHERE source_type = #{sourceType}
  AND source_id = #{sourceId}
  AND deleted = FALSE

SELECT * FROM customer_balance_movement
WHERE deleted = FALSE
AND settlement_customer_id = #{query.settlementCustomerId}
AND customer_id = #{query.customerId}
AND type = #{query.type}
AND direction = #{query.direction}
AND occurred_at >= #{query.occurredFrom}
AND occurred_at < #{query.occurredTo}
ORDER BY occurred_at DESC, id DESC
